const quotePremium = (items: QuoteItem[]): number => {
  const policyBase = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
  return Math.ceil(policyBase + firstInsurance + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quote = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quote.items) }] };
};
